def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in planets or planet2 not in planets:
        return ()

    orbit_order = {planet: index for index, planet in enumerate(planets)}

    start = min(orbit_order[planet1], orbit_order[planet2])
    end = max(orbit_order[planet1], orbit_order[planet2])

    result = [planet for planet in planets if start < orbit_order[planet] < end]

    return tuple(sorted(result, key=lambda x: orbit_order[x]))

